package app.mightymorphing.extension.joey;

import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.util.Base64;

/** The r/JoeyForReddit header photo, cropped from the live subreddit banner. */
final class JoeyBanner {
    static final int SOURCE_WIDTH = 430;
    static final int SOURCE_HEIGHT = 128;
    private static final String PNG = "";
    private static Bitmap sBitmap;

    private JoeyBanner() {
    }

    static Bitmap bitmap() {
        if (sBitmap != null && !sBitmap.isRecycled()) return sBitmap;
        try {
            byte[] bytes = Base64.decode(PNG, Base64.DEFAULT);
            sBitmap = BitmapFactory.decodeByteArray(bytes, 0, bytes.length);
        } catch (Throwable ignored) {
        }
        return sBitmap;
    }
}